export function add(a: number, b: number): number {
  return a + b;
}

function isHex64(s: string): boolean {
  return /^[0-9a-f]{64}$/i.test(s);
}

function truncate(s: string, max: number): string {
  return s.length <= max ? s : `${s.slice(0, max - 3)}...`;
}

function stemToCamelCase(stem: string): string {
  return stem.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
}

function emitEntry(entry: SlicePlanEntry): string | null {
  switch (entry.kind) {
    case "pointer":
      return `\n// --- pointer: ${entry.merkleRoot} (${entry.canonicalAstHash.slice(0, 8)}) ---`;

    case "novel-glue":
      return `\n// --- novel-glue: ${entry.canonicalAstHash.slice(0, 8)} ---\n${entry.source}`;

    case "glue": {
      const shortHash = entry.canonicalAstHash.slice(0, 8);
      return (
        `\n// --- glue: ${shortHash} (not in registry) ---\n` +
        entry.source +
        `\n// --- end glue ---`
      );
    }

    case "foreign-leaf":
      // Foreign imports are not inlined into the assembled module.
      return null;
  }
}

function panicCodeToKind(code: number): WasmTrapKind {
  if (code === 0x01) return "oom";
  // 0x42 and all other codes map to "unreachable"
  return "unreachable";
}

function f64Bytes(value: number): number[] {
  const buf = new ArrayBuffer(8);
  new DataView(buf).setFloat64(0, value, /* littleEndian */ true);
  return Array.from(new Uint8Array(buf));
}

export type NumericDomain = "i32" | "i64" | "f64";

// ---------------------------------------------------------------------------
// Local variable declaration
//
// WASM local declarations appear in the function body as (count × valtype)
// pairs that precede the instruction stream. See WASM binary format §5.4.6.
// ---------------------------------------------------------------------------

/**
 * A single group of local variable declarations inside a WASM function body.
 *
 * Example: `{ count: 2, type: "i32" }` encodes two i32 locals in one group.
 * Grouping is an optimisation: adjacent locals of the same type share a count
 * prefix. The visitor emits one group per unique type unless it knows multiple
 * consecutive locals share a type.
 */
export interface LocalDecl {
  readonly count: number;
  readonly type: NumericDomain;
}

// ---------------------------------------------------------------------------
// WasmFunction — the primary output of LoweringVisitor per exported function
// ---------------------------------------------------------------------------

/**
 * Intermediate representation for a single compiled WASM function.
 *
 * The fields map directly to the WASM binary code section structure:
 *   - `locals` — local variable declarations (not including params, which are
 *     implicit in WASM and assigned the first local slots by convention)
 *   - `body` — opcode stream as raw bytes (each element is one byte)
 *
 * The wave-2 emitter in wasm-backend.ts serialises this as:
 *   uleb128(locals.length)
 *   [ uleb128(d.count), valtype(d.type) for d in locals ]
 *   [ b for b in body ]
 *   0x0b  (end)
 *
 * Note: the `end` opcode (0x0b) is appended by the emitter, NOT included in
 * `body`, so visitor implementations must not include it.
 */
export interface WasmFunction {
  /** Explicit local variable declarations (params are implicit, not listed here). */
  readonly locals: ReadonlyArray<LocalDecl>;
  /**
   * Opcode byte stream. Each number is a byte in [0, 255].
   * Does NOT include the terminal `end` (0x0b) — the emitter appends that.
   */
  readonly body: ReadonlyArray<number>;
}

// ---------------------------------------------------------------------------
// Helpers for building WasmFunction values during lowering
// ---------------------------------------------------------------------------

/**
 * Encode a WASM numeric type as its binary valtype byte.
 *
 * Spec reference: WASM binary format §5.3.1 (value types).
 *   i32 = 0x7f, i64 = 0x7e, f64 = 0x7c
 */
export function valtypeByte(domain: NumericDomain): number {
  switch (domain) {
    case "i32":
      return 0x7f;
    case "i64":
      return 0x7e;
    case "f64":
      return 0x7c;
  }
}

function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export function isLocalTriplet(t: BlockTriplet): t is LocalTriplet {
  return t.kind !== "foreign";
}

function normalizeBase(remote: RemotePeer): string {
  return remote.endsWith("/") ? remote.slice(0, -1) : remote;
}

export function buildIntentCardQuery(ctx: EmissionContext): IntentCardQuery {
  const behavior = ctx.sourceContext ? `${ctx.intent} ${ctx.sourceContext}` : ctx.intent;
  return { behavior, inputs: [], outputs: [] };
}

export function buildSkeletonSpec(intent: string): ContractSpec {
  return {
    inputs: [],
    outputs: [],
    behavior: intent,
    guarantees: [],
    errorConditions: [],
    nonFunctional: {
      purity: "pure",
      threadSafety: "safe",
    },
    propertyTests: [],
  };
}

function refBytesToHex(bytes: Uint8Array): string {
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i]?.toString(16).padStart(2, "0");
  }
  return hex;
}

export function isAsciiDigit(c: string): boolean {
  return c.length === 1 && c >= "0" && c <= "9";
}

function isEnoent(err: unknown): boolean {
  return (
    typeof err === "object" &&
    err !== null &&
    "code" in err &&
    (err as { code: unknown }).code === "ENOENT"
  );
}

export function normalizeSource(s: string): string {
  return s.replace(/\r\n/g, "\n").trim();
}

export function candidatesToCombinedScores(candidates: readonly CandidateMatch[]): number[] {
  return candidates.map((c) => {
    const d = c.cosineDistance;
    return Math.max(0, Math.min(1, 1 - (d * d) / 4));
  });
}

function propsArtifactPath(atomName: string): string {
  return `${atomName}.props.ts`;
}

function collapseWhitespace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function normalize(id: string): string {
  let s = id.trim();
  if (s.startsWith("(") && s.endsWith(")")) {
    s = s.slice(1, -1).trim();
  }
  s = s.replace(/\s+/g, "-");
  return s.toUpperCase();
}

function mapParam(param: IntentParam): SpecYakParameter {
  return {
    name: param.name,
    type: param.typeHint,
    description: param.description,
  };
}

function deriveSpecName(behavior: string, canonicalAstHash: string): string {
  const prefix = behavior
    .slice(0, 30)
    .replace(/\W+/g, "-")
    .replace(/^-+|-+$/g, "");

  const hashSuffix = canonicalAstHash.slice(-6);

  return `${prefix}-${hashSuffix}`;
}

function normalize(s: string): string {
  return s
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[.;!?,]+$/, "");
}

/**
 * Adapted from lukeed/mri (MIT License)
 *  https://github.com/lukeed/mri  (commit: 20c4fb7 — latest main as of 2025-01)
 *
 * SPDX-License-Identifier: MIT
 *
 * Implements the core algorithmic shape: positional args, --flag, --flag=value,
 * --flag value, alias resolution. Simplified TS adaptation for v0.7 demo.
 *
 * @decision DEC-DECOMPOSE-STAGE-015-CORRECTION
 * title: TS argv-parser as mri demo target (not literal mri JS vendoring)
 * status: decided
 * rationale: mri is a JavaScript package; yakcc's IR pipeline is strict-TS.
 *   A TS adaptation preserves the algorithmic shape of mri (the subject of the
 *   demo) while remaining processable by the ts-morph AST canonicalizer. MIT
 *   attribution is preserved in this header. The pipeline behavior is what's
 *   being demonstrated — not byte-equivalent reproduction of the mri source.
 */

// SPDX-License-Identifier: MIT

export interface ParsedArgs {
  readonly _: readonly string[];
  readonly [flag: string]: unknown;
}

export interface ParseOptions {
  /** Alias map: key is canonical flag name, value is array of alias strings. */
  readonly alias?: Readonly<Record<string, readonly string[]>>;
  /** Flags that are treated as booleans (no value consumed). */
  readonly boolean?: readonly string[];
  /** Default values applied before parsing. */
  readonly default?: Readonly<Record<string, unknown>>;
}

/**
 * Parse an argv array into flags and positional arguments.
 *
 * Single function, single control-flow boundary — deliberately shaped so that
 * isAtom() classifies it as atomic at the default maxCF=1 threshold. This
 * exercises the v0.7 universalize() path where the root AtomLeaf maps to a
 * single NovelGlueEntry with an attached intentCard.
 *
 * @param argv    - Argument strings to parse (e.g. process.argv.slice(2)).
 * @param options - Optional alias, boolean, and default configuration.
 */
export function parseArgv(argv: readonly string[], options?: ParseOptions): ParsedArgs {
  const result: Record<string, unknown> = { _: [] };

  // Apply defaults before scanning
  const defaults = options?.default ?? {};
  for (const [k, v] of Object.entries(defaults)) {
    result[k] = v;
  }

  // Build reverse alias map: alias string → canonical name
  const aliases = options?.alias ?? {};
  const canonicalOf: Record<string, string> = {};
  for (const [canonical, aliasArr] of Object.entries(aliases)) {
    for (const a of aliasArr) {
      canonicalOf[a] = canonical;
    }
    canonicalOf[canonical] = canonical;
  }

  const boolFlags = new Set<string>(options?.boolean ?? []);

  const set = (raw: string, val: unknown): void => {
    const key = canonicalOf[raw] ?? raw;
    result[key] = val;
  };

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === undefined) {
      i++;
      continue;
    }
    if (arg === "--") {
      // Everything after `--` is positional
      for (let j = i + 1; j < argv.length; j++) {
        (result._ as string[]).push(argv[j] ?? "");
      }
      break;
    }

    if (arg.startsWith("--")) {
      const body = arg.slice(2);
      const eqIdx = body.indexOf("=");
      if (eqIdx !== -1) {
        // --flag=value
        set(body.slice(0, eqIdx), body.slice(eqIdx + 1));
      } else {
        const canonical = canonicalOf[body] ?? body;
        const isBool = boolFlags.has(body) || boolFlags.has(canonical);
        const next = argv[i + 1];
        if (!isBool && next !== undefined && !next.startsWith("-")) {
          set(body, next);
          i++;
        } else {
          set(body, !isBool || result[canonical] !== false);
        }
      }
    } else if (arg.startsWith("-") && arg.length > 1) {
      // Expand short flags: -abc → -a -b -c
      const chars = arg.slice(1);
      for (let ci = 0; ci < chars.length; ci++) {
        const ch = chars[ci];
        if (ch === undefined) continue;
        const isLast = ci === chars.length - 1;
        const canonical = canonicalOf[ch] ?? ch;
        const isBool = boolFlags.has(ch) || boolFlags.has(canonical);
        if (isLast && !isBool) {
          const next = argv[i + 1];
          if (next !== undefined && !next.startsWith("-")) {
            set(ch, next);
            i++;
          } else {
            set(ch, true);
          }
        } else {
          set(ch, true);
        }
      }
    } else {
      (result._ as string[]).push(arg);
    }
    i++;
  }

  return result as ParsedArgs;
}

function insideSnapshot(p: string): boolean {
  return p.startsWith("/snapshot/") || p.startsWith("/snapshot");
}

// SPDX-License-Identifier: MIT
// @decision DEC-TRIPLET-L0-ONLY-019: The proof/manifest.json schema accepts
// smt_cert / lean_proof / coq_proof artifact kinds at the type level, but the
// L0 manifest validator (validateProofManifestL0) rejects any artifact kind
// other than "property_tests". L1/L2/L3 validators are deferred.
// Status: decided (MASTER_PLAN.md)
// Rationale: v0.6 ships L0 only; the schema must be expressive for future levels
// but the L0 enforcement point is explicit and named so future levels add a new
// validator rather than loosening this one.

// ---------------------------------------------------------------------------
// ProofManifest types
// ---------------------------------------------------------------------------

/**
 * The artifact kinds the proof/manifest.json schema recognizes.
 *
 * - property_tests: a fast-check property-test corpus (required at L0).
 * - smt_cert: an SMT-solver certificate (valid at L2+; schema-valid at L0 but
 *   rejected by validateProofManifestL0).
 * - lean_proof: a Lean proof artifact (valid at L3+; schema-valid at L0 but
 *   rejected by validateProofManifestL0).
 * - coq_proof: a Coq proof artifact (valid at L3+; schema-valid at L0 but
 *   rejected by validateProofManifestL0).
 * - fuzz_bounds_witness: a bounded fuzzing result artifact (valid at L2+;
 *   schema-valid at L0 but rejected by validateProofManifestL0).
 */
export type ArtifactKind =
  | "property_tests"
  | "smt_cert"
  | "lean_proof"
  | "coq_proof"
  | "fuzz_bounds_witness";

/**
 * One artifact entry in the proof/manifest.json.
 *
 * The path is relative to the proof/ directory. Each artifact kind has a
 * registered checker in the registry's verifier set. The manifest is part of
 * the BlockMerkleRoot, so attestations cover not just the proof bytes but
 * the declaration of what kind of proof it is.
 */
export interface ProofArtifact {
  /** The kind of artifact and which checker to invoke. */
  readonly kind: ArtifactKind;
  /** Path to the artifact file, relative to the proof/ directory. */
  readonly path: string;
  /**
   * For smt_cert artifacts: the SMT theory tags used in this certificate.
   * Optional for other kinds.
   */
  readonly theory?: readonly string[] | undefined;
  /**
   * For lean_proof / coq_proof artifacts: the checker version used.
   * E.g. "lean4@4.7.0". Optional for other kinds.
   */
  readonly checker?: string | undefined;
}

/**
 * The proof/manifest.json schema.
 *
 * The manifest declares which verification artifacts are present in proof/
 * and which checker each invokes. The order of artifacts in this array is
 * the stable order used when computing proof_root in blockMerkleRoot():
 *   proof_root = BLAKE3(canonicalize(manifest.json) || concat(BLAKE3(artifact_bytes_in_manifest_order)))
 *
 * The manifest itself is included in the Merkle derivation so that changing
 * the manifest (e.g. adding an artifact declaration) changes the block identity,
 * even if no artifact bytes changed.
 */
export interface ProofManifest {
  /**
   * Ordered list of verification artifacts in this block's proof/ directory.
   * The order determines the artifact byte concatenation order in proof_root.
   */
  readonly artifacts: readonly ProofArtifact[];
}

// ---------------------------------------------------------------------------
// Validators
// ---------------------------------------------------------------------------

/**
 * Validate and narrow an unknown value to ProofManifest for L0 blocks.
 *
 * L0 validation rules:
 * 1. The value must be a non-null object with an "artifacts" array.
 * 2. The "artifacts" array must contain exactly one entry with kind "property_tests".
 * 3. All other artifact kinds (smt_cert, lean_proof, coq_proof, fuzz_bounds_witness)
 *    are schema-valid at the type level but rejected by this L0-specific validator.
 *    L1+/L2+/L3+ validators are deferred (DEC-TRIPLET-L0-ONLY-019).
 * 4. Each artifact entry must have a non-empty "path" string.
 *
 * Throws a TypeError with a descriptive message on invalid input.
 */
export function validateProofManifestL0(value: unknown): ProofManifest {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError("validateProofManifestL0: expected a non-null object");
  }

  const obj = value as Record<string, unknown>;

  if (!("artifacts" in obj) || obj.artifacts === undefined) {
    throw new TypeError('validateProofManifestL0: missing required field "artifacts"');
  }

  if (!Array.isArray(obj.artifacts)) {
    throw new TypeError('validateProofManifestL0: field "artifacts" must be an array');
  }

  const artifacts = obj.artifacts as unknown[];

  if (artifacts.length === 0) {
    throw new TypeError(
      "validateProofManifestL0: L0 manifest must contain at least one artifact; " +
        'expected exactly one "property_tests" entry',
    );
  }

  // Validate each artifact entry and enforce L0 artifact-kind constraint.
  let propertyTestsCount = 0;
  for (let i = 0; i < artifacts.length; i++) {
    const entry = artifacts[i];
    if (entry === null || typeof entry !== "object" || Array.isArray(entry)) {
      throw new TypeError(`validateProofManifestL0: artifacts[${i}] must be a non-null object`);
    }

    const artifact = entry as Record<string, unknown>;

    if (!("kind" in artifact) || artifact.kind === undefined) {
      throw new TypeError(`validateProofManifestL0: artifacts[${i}] missing required field "kind"`);
    }

    if (!("path" in artifact) || artifact.path === undefined) {
      throw new TypeError(`validateProofManifestL0: artifacts[${i}] missing required field "path"`);
    }

    if (typeof artifact.path !== "string" || artifact.path.length === 0) {
      throw new TypeError(
        `validateProofManifestL0: artifacts[${i}].path must be a non-empty string`,
      );
    }

    const kind = artifact.kind;

    // L0 enforcement: only property_tests is allowed.
    if (kind !== "property_tests") {
      throw new TypeError(
        `validateProofManifestL0: artifacts[${i}].kind is "${String(kind)}" — only "property_tests" is allowed at L0. smt_cert, lean_proof, coq_proof, and fuzz_bounds_witness are schema-valid types but require L2+/L3+ validators (DEC-TRIPLET-L0-ONLY-019).`,
      );
    }

    propertyTestsCount++;
  }

  // L0 requires exactly one property_tests artifact.
  if (propertyTestsCount !== 1) {
    throw new TypeError(
      `validateProofManifestL0: L0 manifest must declare exactly one "property_tests" artifact; found ${propertyTestsCount}`,
    );
  }

  return obj as unknown as ProofManifest;
}

function buildFragmentFallback(stmtCount: number, byteCount: number): string {
  return `source fragment (${stmtCount} statements, ${byteCount} bytes)`;
}

function isTestEmission(code: string, filePath: string | undefined): boolean {
  if (filePath !== undefined && /\.(test|spec)\.[jt]sx?$/.test(filePath)) {
    return true;
  }
  // Content heuristic: test-framework API calls.
  return /(?:^|\s)(?:describe|it|test|expect|beforeEach|afterEach|beforeAll|afterAll)\s*\(/.test(
    code,
  );
}

function extractFunctionName(code: string): string | null {
  return /(?:export\s+(?:async\s+)?function\s+)(\w+)/.exec(code)?.[1] ?? null;
}

export function renderAtomNewComment(blockMerkleRoot: string, atomName: string): string {
  const shortBmr = blockMerkleRoot.slice(0, 8);
  return `// @atom-new: ${shortBmr} — yakcc:${atomName}`;
}

export function outcomeFromResponse(
  response: HookResponse,
  outcomeOverride?: "atomized",
): "registry-hit" | "synthesis-required" | "passthrough" | "atomized" {
  if (outcomeOverride !== undefined) return outcomeOverride;
  return response.kind;
}

export function cosineDistanceToCombinedScore(cosineDistance: number): number {
  return Math.max(0, Math.min(1, 1 - (cosineDistance * cosineDistance) / 4));
}

function benchmarkQueryToIntentQuery(q: BenchmarkQueryCard): {
  behavior: string;
  inputs: ReadonlyArray<{ name: string; typeHint: string }>;
  outputs: ReadonlyArray<{ name: string; typeHint: string }>;
} {
  const inputs = (q.signature?.inputs ?? []).map((p) => ({
    name: p.name,
    typeHint: p.type,
  }));
  const outputs = (q.signature?.outputs ?? []).map((p) => ({
    name: p.name,
    typeHint: p.type,
  }));
  return { behavior: q.behavior, inputs, outputs };
}

export function worstHitRateEntries(
  results: readonly QueryResult[],
  n = 3,
): readonly QueryResult[] {
  return [...results].sort((a, b) => a.top1Score - b.top1Score).slice(0, n);
}

export function computePrecisionAt1(results: readonly QueryResult[]): number {
  const eligible = results.filter((r) => r.expectedAtom !== null);
  if (eligible.length === 0) return 0;
  const correct = eligible.filter((r) => r.top1Correct).length;
  return correct / eligible.length;
}

export function computeRecallAtK(results: readonly QueryResult[]): number {
  const eligible = results.filter((r) => r.expectedAtom !== null);
  if (eligible.length === 0) return 0;
  const found = eligible.filter((r) => r.expectedAtomRank !== null).length;
  return found / eligible.length;
}

export function computeAtomComplexity(atom: AtomLike): number {
  const transitiveNodes =
    (atom.spec.inputs?.length ?? 0) +
    (atom.spec.outputs?.length ?? 0) +
    (atom.spec.guarantees?.length ?? 0);

  return transitiveNodes + 5 * atom.exportedSurface + 2 * atom.transitiveDeps;
}

export function computeNeedComplexity(callSite: CallSiteAnalysis): number {
  return Math.max(1, callSite.bindingsUsed * callSite.statementCount);
}

function buildSuggestion(
  primary: DriftMetric,
  metrics: DriftWindowMetrics,
  cfg: Layer5Config,
): string {
  const w = metrics.windowSize;
  switch (primary) {
    case "specificity_floor":
      return (
        `Layer 5 drift alert: mean specificity score ${metrics.meanSpecificityScore.toFixed(3)} ` +
        `is below floor ${cfg.specificityFloor} over a ${w}-event window. ` +
        `The LLM is producing consistently vague intents. ` +
        `Follow the descent-and-compose discipline to produce more specific queries.`
      );
    case "descent_bypass_rate":
      return (
        `Layer 5 drift alert: descent-bypass-warning rate ${(metrics.descentBypassRate * 100).toFixed(1)}% ` +
        `exceeds max ${(cfg.descentBypassMax * 100).toFixed(1)}% over a ${w}-event window. ` +
        `The LLM is skipping the required descent path before substitution. ` +
        `Record enough import-intercept misses before calling substitute.`
      );
    case "result_set_median":
      return (
        `Layer 5 drift alert: median result-set size ${metrics.medianResultSetSize} ` +
        `exceeds max ${cfg.resultSetMedianMax} over a ${w}-event window. ` +
        `Registry queries are persistently too broad. ` +
        `Decompose or narrow the intent before querying.`
      );
    case "ratio_median":
      return (
        `Layer 5 drift alert: median atom/need ratio ${metrics.medianAtomRatio.toFixed(2)} ` +
        `exceeds max ${cfg.ratioMedianMax} over a ${w}-event window. ` +
        `The LLM is consistently over-substituting large atoms for small call sites. ` +
        `Prefer atoms whose complexity is closer to the call-site need.`
      );
  }
}

function tokenize(intent: string): readonly string[] {
  return intent
    .trim()
    .split(/\s+/)
    .filter((t) => t.length > 0)
    .map((t) => t.toLowerCase().replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ""));
}

export function withCompletion(state: ShaveOnMissState, key: string): ShaveOnMissState {
  if (state.completedBindings.includes(key)) return state;
  return {
    ...state,
    completedBindings: [...state.completedBindings, key],
  };
}

export function withHitIncrement(state: ShaveOnMissState, key: string): ShaveOnMissState {
  const prev = state.hitCounts[key] ?? 0;
  return {
    ...state,
    hitCounts: { ...state.hitCounts, [key]: prev + 1 },
  };
}

export function makeBindingKey(packageName: string, binding: string): string {
  return `${packageName}::${binding}`;
}

// SPDX-License-Identifier: MIT
//
// @decision DEC-V0-B4-SEED-lru-node-001
// @title lru-node: doubly-linked list node for O(1) LRU eviction
// @status accepted
// @rationale
//   The lru-cache-with-ttl B4 task requires a doubly-linked list as the ordered
//   eviction structure. O(1) insert-at-head, O(1) remove-any, and O(1)
//   move-to-head all depend on prev/next pointer wiring. This atom is the
//   fundamental allocation unit: create a node, wire its pointers externally.
//
//   Design decisions:
//   (A) MUTABLE FIELDS: prev and next are mutable (not readonly) because the
//       LRU algorithm must rewire pointers in-place on every cache hit. Readonly
//       fields would require allocating a new node on every access -- O(n) space
//       for an O(n) operation sequence, defeating the purpose.
//
//   (B) PLAIN OBJECT RETURN: Returns a plain JS object that satisfies the
//       LruNode interface. No class needed; the interface provides the type
//       contract and the plain-object implementation avoids prototype overhead.
//
//   (C) UNKNOWN VALUE TYPE: value is typed as unknown (not generic) to keep
//       the atom strictly within the validated TypeScript subset. Callers cast
//       to their concrete type after retrieval, which is idiomatic for a low-
//       level building block.
//
//   Reference: Cormen et al., "Introduction to Algorithms" 4th ed., Section 10.2
//   (doubly linked lists) and Section 20.1 (hash table + list for O(1) LRU).

/** A node in a doubly-linked intrusive list used by the LRU eviction policy. */
export interface LruNode {
  key: string;
  value: unknown;
  prev: LruNode | null;
  next: LruNode | null;
}

/**
 * Allocate a new LRU list node for the given key-value pair.
 *
 * Both prev and next are initialised to null. The caller is responsible for
 * wiring pointers when inserting the node into the eviction list.
 *
 * @param key   - Cache key. Stored by reference (no copy).
 * @param value - Cached value. Stored by reference (no copy).
 * @returns A new LruNode with null prev/next pointers.
 */
export function makeLruNode(key: string, value: unknown): LruNode {
  return { key, value, prev: null, next: null };
}

// SPDX-License-Identifier: MIT
//
// @decision DEC-V0-B4-SEED-semver-component-parser-001
// @title semver-component-parser: version-string parser for MAJOR.MINOR.PATCH[-pre][+build]
// @status accepted
// @rationale
//   The semver-range-satisfies B4 task requires parsing version strings into
//   their numeric and string components before any range comparison. This atom
//   implements the parsing primitive so the range-comparison logic can operate
//   on structured data rather than raw strings.
//
//   Design decisions:
//   (A) SPLIT THEN PARSE: The implementation splits the input string rather
//       than using a hand-rolled character-position parser. The split approach
//       is more readable and the O(n) allocation cost is acceptable for version
//       strings, which are short (typically < 30 chars). A position-based
//       parser would save zero allocations in practice at the cost of
//       significant code complexity.
//
//   (B) BUILD BEFORE PRERELEASE: The '+' (build metadata) separator is handled
//       AFTER splitting on '-' (prerelease). If the patch field contains '+',
//       we split again. This correctly handles '1.0.0-beta+sha' where '-beta'
//       is prerelease and 'sha' is build metadata appended to the patch field.
//       Order matters: split on '-' first, then on '+'.
//
//   (C) NO SEMANTIC VALIDATION OF IDENTIFIERS: Prerelease and build identifier
//       characters are not validated (the spec only requires capturing them as
//       strings). Full validation per semver.org spec section 9-10 would add
//       complexity without benefit for the B4 task's comparator use-case.
//
//   (D) EXPLICIT GUARD FOR ARRAY INDEXING: After verifying parts.length === 3
//       via SyntaxError throw, TypeScript still types parts[n] as
//       string | undefined. We use explicit string coercion ("" fallback via
//       ?? "") to satisfy the type checker while maintaining the invariant
//       that the value is always defined at this point in the code.
//
//   Reference: Semantic Versioning 2.0.0 specification (semver.org),
//   sections 2-10. Tom Preston-Werner, original author.

/** Parsed components of a semver version string. */
export interface SemverComponents {
  readonly major: number;
  readonly minor: number;
  readonly patch: number;
  readonly prerelease: string | null;
  readonly build: string | null;
}

/**
 * Parse a semver version string into its numeric and string components.
 *
 * Handles the full MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD] grammar.
 * Prerelease and build identifiers are captured as raw strings without
 * further validation.
 *
 * @param input - Version string to parse.
 * @returns Parsed SemverComponents.
 * @throws SyntaxError if input does not match MAJOR.MINOR.PATCH structure.
 */
export function parseSemver(input: string): SemverComponents {
  if (input.length === 0) {
    throw new SyntaxError("parseSemver: empty input");
  }

  // Separate prerelease suffix (everything after first '-')
  let prerelease: string | null = null;
  let build: string | null = null;

  // Find build metadata first ('+' in the original string)
  const plusIndex = input.indexOf("+");
  let versionWithPre = input;
  if (plusIndex !== -1) {
    build = input.slice(plusIndex + 1);
    versionWithPre = input.slice(0, plusIndex);
  }

  // Find prerelease ('-' in the version-without-build string)
  const dashIndex = versionWithPre.indexOf("-");
  let coreVersion = versionWithPre;
  if (dashIndex !== -1) {
    prerelease = versionWithPre.slice(dashIndex + 1);
    coreVersion = versionWithPre.slice(0, dashIndex);
  }

  // Parse MAJOR.MINOR.PATCH
  const parts = coreVersion.split(".");
  if (parts.length !== 3) {
    throw new SyntaxError(
      `parseSemver: expected MAJOR.MINOR.PATCH, got ${JSON.stringify(coreVersion)}`,
    );
  }

  // After the length guard above, parts[0..2] are always defined.
  // The ?? "" fallback satisfies TypeScript's string | undefined narrowing
  // while being unreachable in practice.
  const majorStr = parts[0] ?? "";
  const minorStr = parts[1] ?? "";
  const patchStr = parts[2] ?? "";

  const major = Number.parseInt(majorStr, 10);
  const minor = Number.parseInt(minorStr, 10);
  const patch = Number.parseInt(patchStr, 10);

  if (Number.isNaN(major) || major < 0) {
    throw new SyntaxError(`parseSemver: invalid MAJOR component ${JSON.stringify(majorStr)}`);
  }
  if (Number.isNaN(minor) || minor < 0) {
    throw new SyntaxError(`parseSemver: invalid MINOR component ${JSON.stringify(minorStr)}`);
  }
  if (Number.isNaN(patch) || patch < 0) {
    throw new SyntaxError(`parseSemver: invalid PATCH component ${JSON.stringify(patchStr)}`);
  }

  return { major, minor, patch, prerelease, build };
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-ASCIICHAR-001: ascii-char is the positional consumption primitive.
// Status: implemented (WI-006)
// Rationale: Many parsing blocks need to consume a character at a known offset without
// interpretation. This block is the positional-read utility that others compose.

export function asciiChar(input: string, position: number): string {
  if (position < 0 || position >= input.length) {
    throw new RangeError(`Position ${position} out of bounds for input of length ${input.length}`);
  }
  const code = input.charCodeAt(position);
  if (code > 127) {
    throw new RangeError(`Non-ASCII character at position ${position}: code ${code}`);
  }
  return input[position] as string;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-BRACKET-001: bracket matches a single bracket char and returns next position.
// Status: implemented (WI-006)
// Rationale: Bracket matching is a hot path in list parsing. Returning the post-bracket position
// follows the positional combinator convention used by all other blocks in this corpus.

export function bracket(input: string, position: number, kind: "[" | "]"): number {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length) {
    throw new SyntaxError(`Expected '${kind}' at position ${position} but reached end of input`);
  }
  if (input[position] !== kind) {
    throw new SyntaxError(
      `Expected '${kind}' at position ${position} but found ${JSON.stringify(input[position])}`,
    );
  }
  return position + 1;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-CHARCODE-001: char-code exposes char-code lookup as an explicit contract.
// Status: implemented (WI-006)
// Rationale: Multiple blocks rely on charCodeAt arithmetic. Making it an explicit block
// documents the zero-extension property (always non-negative) and enables registry reuse.

export function charCode(input: string, position: number): number {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length) {
    throw new RangeError(`Position ${position} out of bounds for input of length ${input.length}`);
  }
  return input.charCodeAt(position);
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-DIGITORTHROW-001: digit-or-throw wraps positional digit reading with context.
// Status: implemented (WI-006)
// Rationale: Callers that have already peeked and confirmed a digit want a single call that
// reads-and-advances with a descriptive error. This combinator adds the position context
// that the raw digit() function lacks.

export function digitOrThrow(input: string, position: number): readonly [number, number] {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length) {
    throw new SyntaxError(`Expected digit at position ${position} but reached end of input`);
  }
  const c = input[position] as string;
  if (c < "0" || c > "9") {
    throw new SyntaxError(`Expected digit at position ${position} but found ${JSON.stringify(c)}`);
  }
  return [c.charCodeAt(0) - 48, position + 1] as const;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-EOFCHECK-001: eof-check is the trailing-input rejection gate.
// Status: implemented (WI-006)
// Rationale: A parser that accepts input must also reject trailing garbage. This block
// is the explicit end-of-input assertion that composition blocks call after parsing.

export function eofCheck(input: string, position: number): void {
  if (position > input.length) {
    throw new RangeError(`Position ${position} overruns input of length ${input.length}`);
  }
  if (position < input.length) {
    throw new SyntaxError(
      `Expected end of input at position ${position} but found ${JSON.stringify(input.slice(position))}`,
    );
  }
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-INTEGER-001: integer composes digit; returns value + new position as a tuple.
// Status: implemented (WI-006)
// Rationale: Returning [value, newPosition] keeps the block pure while providing both the
// parsed value and the advanced cursor to the caller without a mutable context object.

export function integer(input: string, position: number): readonly [number, number] {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length || input[position] === undefined) {
    throw new SyntaxError(`Expected digit at position ${position} but reached end of input`);
  }
  const first = input[position] as string;
  if (first < "0" || first > "9") {
    throw new SyntaxError(
      `Expected digit at position ${position} but found ${JSON.stringify(first)}`,
    );
  }
  let value = 0;
  let pos = position;
  while (pos < input.length) {
    const c = input[pos] as string;
    if (c < "0" || c > "9") break;
    value = value * 10 + (c.charCodeAt(0) - 48);
    pos++;
  }
  return [value, pos] as const;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-SIGNEDINT-001: signed-integer extends integer with optional leading minus.
// Status: implemented (WI-006)
// Rationale: A common extension of unsigned integer parsing. Demonstrates contract refinement:
// signed-integer has a strictly wider input domain than integer but same output type contract.

export function signedInteger(input: string, position: number): readonly [number, number] {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length) {
    throw new SyntaxError(`Expected digit or '-' at position ${position} but reached end of input`);
  }

  let pos = position;
  let sign = 1;

  if (input[pos] === "-") {
    sign = -1;
    pos++;
    if (pos >= input.length) {
      throw new SyntaxError(`Expected digit after '-' at position ${pos} but reached end of input`);
    }
  }

  const c = input[pos] as string;
  if (c < "0" || c > "9") {
    throw new SyntaxError(`Expected digit at position ${pos} but found ${JSON.stringify(c)}`);
  }

  let value = 0;
  while (pos < input.length) {
    const ch = input[pos] as string;
    if (ch < "0" || ch > "9") break;
    value = value * 10 + (ch.charCodeAt(0) - 48);
    pos++;
  }

  return [sign * value, pos] as const;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-WHITESPACE-001: whitespace skipping returns a new position, not stripped text.
// Status: implemented (WI-006)
// Rationale: Position-returning parsers compose without allocating substrings.
// Returning the new position after whitespace is cheaper and composable with all other blocks.

export function whitespace(input: string, position: number): number {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  let pos = position;
  while (pos < input.length) {
    const c = input[pos];
    if (c !== " " && c !== "\t") {
      break;
    }
    pos++;
  }
  return pos;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-STRFROMPOS-001: substring extraction at a position is a reusable primitive.
// Status: implemented (WI-006)
// Rationale: Multiple blocks need to extract substrings starting at a position. Centralising
// bounds checking avoids each block duplicating the same guard logic.

export function stringFromPosition(input: string, start: number, end: number): string {
  if (start < 0 || end < 0) {
    throw new RangeError(`Negative index: start=${start}, end=${end}`);
  }
  if (start > end) {
    throw new RangeError(`start ${start} > end ${end}`);
  }
  if (end > input.length) {
    throw new RangeError(`end ${end} exceeds input length ${input.length}`);
  }
  return input.slice(start, end);
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-POSSTEP-001: position advancement is an explicit operation, not implicit mutation.
// Status: implemented (WI-006)
// Rationale: Parser blocks work with immutable position values. positionStep returns
// the new position rather than mutating any state, keeping all blocks pure.

export function positionStep(position: number, n: number, inputLength: number): number {
  if (position < 0) {
    throw new RangeError(`position ${position} is negative`);
  }
  if (n < 0) {
    throw new RangeError(`step ${n} is negative`);
  }
  const next = position + n;
  if (next > inputLength) {
    throw new RangeError(
      `position ${position} + step ${n} = ${next} exceeds input length ${inputLength}`,
    );
  }
  return next;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-PEEKCHAR-001: peek-without-advance is a fundamental parser combinator primitive.
// Status: implemented (WI-006)
// Rationale: Many parsing decisions are made by inspecting the next character without consuming it.
// Separating peek from consume avoids coupling lookahead to position advancement.

export function peekChar(input: string, position: number): string | null {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  if (position >= input.length) {
    return null;
  }
  return input[position] as string;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-NONASCII-001: non-ascii-rejector is a full-input validation gate.
// Status: implemented (WI-006)
// Rationale: The seed corpus parsers only handle ASCII. Failing fast on non-ASCII at the
// entry point gives a clear error rather than a cryptic failure mid-parse.

export function nonAsciiRejector(input: string): void {
  for (let i = 0; i < input.length; i++) {
    const code = input.charCodeAt(i);
    if (code > 127) {
      throw new RangeError(`Non-ASCII character at position ${i}: code ${code}`);
    }
  }
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-COMMASEP-001: comma-separated-integers parses the interior of a list after the first element.
// Status: implemented (WI-006)
// Rationale: The import-type declarations below declare the composition graph. Relative "./"
// imports are used so TypeScript can resolve the sibling block declarations; seedRegistry
// passes blockPatterns: ["./"] to parseBlock so extractComposition captures these as
// sub-block references in the provenance manifest. `import type` is used because
// strict-subset validates each block in an isolated single-file ts-morph project where
// sibling value imports resolve to `any` and fail no-untyped-imports. Type-only imports
// are unconditionally skipped by that rule.
// Composition graph — captured by extractComposition via the @yakcc/seeds/ builtin pattern.
// WI-T05-fix: import paths use "@yakcc/seeds/blocks/<name>" so the compile resolver's
// SUB_BLOCK_IMPORT_RE (which matches "@yakcc/seeds/" prefix) can extract sub-block deps.
// All imports are "import type" so the strict-subset validator skips them unconditionally
// and vitest/Vite erases them at transpile time (no runtime module resolution needed).
import type { comma } from "@yakcc/seeds/blocks/comma";
import type { integer } from "@yakcc/seeds/blocks/integer";
import type { optionalWhitespace } from "@yakcc/seeds/blocks/optional-whitespace";
import type { peekChar } from "@yakcc/seeds/blocks/peek-char";

// Suppress "imported but never used as a value" by surfacing type aliases.
type _Comma = typeof comma;
type _Integer = typeof integer;
type _OptionalWhitespace = typeof optionalWhitespace;
type _PeekChar = typeof peekChar;

// ---------------------------------------------------------------------------
// Implementation
//
// Each section mirrors one sub-block's contract boundary exactly:
//   peekChar(input, pos)            → return char at pos or null (no advance)
//   comma(input, pos)               → assert ','; return pos+1
//   optionalWhitespace(input, pos)  → skip spaces/tabs; return new pos
//   integer(input, pos)             → parse digits; return [value, newPos]
// ---------------------------------------------------------------------------

export function commaSeparatedIntegers(
  input: string,
  position: number,
): readonly [ReadonlyArray<number>, number] {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }
  const values: number[] = [];
  let pos = position;

  // peekChar: inspect next char without advancing; loop while ',' is next.
  while (pos < input.length && input[pos] === ",") {
    // comma: assert ',' and advance past it.
    pos++;

    // optionalWhitespace: skip spaces/tabs after comma.
    while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
      pos++;
    }

    // integer: parse one or more digits.
    if (pos >= input.length) {
      throw new SyntaxError(
        `Expected integer after ',' at position ${pos} but reached end of input`,
      );
    }
    const c = input[pos] as string;
    if (c < "0" || c > "9") {
      throw new SyntaxError(
        `Expected integer after ',' at position ${pos} but found ${JSON.stringify(c)}`,
      );
    }
    let value = 0;
    while (pos < input.length) {
      const ch = input[pos] as string;
      if (ch < "0" || ch > "9") break;
      value = value * 10 + (ch.charCodeAt(0) - 48);
      pos++;
    }
    values.push(value);

    // optionalWhitespace: skip spaces/tabs after integer.
    while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
      pos++;
    }
  }

  return [values, pos] as const;
}

// SPDX-License-Identifier: MIT
// @decision DEC-SEEDS-NONEMPTYLIST-001: nonempty-list-content parses interior with at least one element.
// Status: implemented (WI-006)
// Rationale: The import-type declarations below declare the composition graph. Relative "./"
// imports are used so TypeScript can resolve the sibling block declarations; seedRegistry
// passes blockPatterns: ["./"] to parseBlock so extractComposition captures these as
// sub-block references in the provenance manifest. `import type` is used because
// strict-subset validates each block in an isolated single-file ts-morph project where
// sibling value imports resolve to `any` and fail no-untyped-imports. Type-only imports
// are unconditionally skipped by that rule.
// Composition graph — captured by extractComposition via the @yakcc/seeds/ builtin pattern.
// WI-T05-fix: import paths use "@yakcc/seeds/blocks/<name>" so the compile resolver's
// SUB_BLOCK_IMPORT_RE (which matches "@yakcc/seeds/" prefix) can extract sub-block deps.
// All imports are "import type" so the strict-subset validator skips them unconditionally
// and vitest/Vite erases them at transpile time (no runtime module resolution needed).
import type { bracket } from "@yakcc/seeds/blocks/bracket";
import type { comma } from "@yakcc/seeds/blocks/comma";
import type { integer } from "@yakcc/seeds/blocks/integer";
import type { optionalWhitespace } from "@yakcc/seeds/blocks/optional-whitespace";
import type { peekChar } from "@yakcc/seeds/blocks/peek-char";

// Suppress "imported but never used as a value" by surfacing type aliases.
type _Bracket = typeof bracket;
type _Comma = typeof comma;
type _Integer = typeof integer;
type _OptionalWhitespace = typeof optionalWhitespace;
type _PeekChar = typeof peekChar;

// ---------------------------------------------------------------------------
// Implementation
//
// Each section mirrors one sub-block's contract boundary exactly:
//   optionalWhitespace(input, pos)  → skip spaces/tabs; return new pos
//   integer(input, pos)             → parse digits; return [value, newPos]
//   peekChar(input, pos)            → return char at pos or null (no advance)
//   comma(input, pos)               → assert ','; return pos+1
//   bracket(input, pos, ']')        → assert ']'; return pos+1
// ---------------------------------------------------------------------------

export function nonemptyListContent(
  input: string,
  position: number,
): readonly [ReadonlyArray<number>, number] {
  if (position < 0) {
    throw new RangeError(`Position ${position} is negative`);
  }

  const values: number[] = [];
  let pos = position;

  // optionalWhitespace: skip leading spaces/tabs before first integer.
  while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
    pos++;
  }

  // integer: parse first integer (one or more digits required).
  if (pos >= input.length || (input[pos] as string) < "0" || (input[pos] as string) > "9") {
    throw new SyntaxError(
      `Expected digit at position ${pos} but found ${JSON.stringify(input[pos] ?? "EOF")}`,
    );
  }
  let first = 0;
  while (pos < input.length) {
    const c = input[pos] as string;
    if (c < "0" || c > "9") break;
    first = first * 10 + (c.charCodeAt(0) - 48);
    pos++;
  }
  values.push(first);

  // optionalWhitespace: skip whitespace after first integer.
  while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
    pos++;
  }

  // peekChar + comma loop: consume each ", integer" pair while ',' is next.
  while (pos < input.length && input[pos] === ",") {
    // comma: assert ',' and advance.
    pos++;

    // optionalWhitespace: skip whitespace after comma.
    while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
      pos++;
    }

    // integer: parse next integer.
    if (pos >= input.length || (input[pos] as string) < "0" || (input[pos] as string) > "9") {
      throw new SyntaxError(
        `Expected digit after ',' at position ${pos} but found ${JSON.stringify(input[pos] ?? "EOF")}`,
      );
    }
    let val = 0;
    while (pos < input.length) {
      const c = input[pos] as string;
      if (c < "0" || c > "9") break;
      val = val * 10 + (c.charCodeAt(0) - 48);
      pos++;
    }
    values.push(val);

    // optionalWhitespace: skip whitespace after integer.
    while (pos < input.length && (input[pos] === " " || input[pos] === "\t")) {
      pos++;
    }
  }

  // bracket(input, pos, ']'): expect closing ']'.
  if (pos >= input.length || input[pos] !== "]") {
    throw new SyntaxError(
      `Expected ']' at position ${pos} but found ${JSON.stringify(input[pos] ?? "EOF")}`,
    );
  }
  pos++;

  return [values, pos] as const;
}
